-- 1533_repoint_actonmass_bills.sql
--
-- Re-point 284 row-citations of actonmass.org/bills/ pages across 38 URLs. Nothing is retired,
-- no stance value changes, and no row gains or loses a source -- array_replace, one string for one.
--   Review: data/stance-retirement/2026-08-02-actonmass-bills-repoint.md
--   Rollback: data/stance-retirement/2026-08-02-aombills-rollback.json
--
-- 🔴 "THE /bills/ PAGES WERE RENAMED" WAS ONE THIRD RIGHT. The backlog carried this task as 26 renamed
-- URLs. Probing all 42 cited /bills/ URLs against the live site found three different situations, and
-- they need three different remedies:
--   A.  9 URLs /  95 rows -- 404, but the bill IS still on the site under a new path. Cite it.
--   B. 13 URLs /  86 rows -- 404, and the bill is GONE from the current agenda. Only Wayback has it.
--   C. 16 URLs / 103 rows -- still resolve, via the site's own 301. Cite the destination directly, so the
--         citation stops depending on a redirect nobody promised to keep.
--
-- 🔴 THE SITE WAS REBUILT, NOT REORGANISED. actonmass.org is now WordPress; every capture Wayback holds
-- is of the previous Gatsby site. That is why /bills/ vanished wholesale rather than shifting -- and why
-- guessing the transform was the wrong instinct. The mapping here is derived, not invented:
--   · group C from the site's OWN 301 targets;
--   · group A by joining bill NAME across two sources -- the archived legislator scorecards give
--     old-slug -> bill name via their /bills/<slug> hrefs, and the live pages give new-path -> bill name
--     via their <h1>. Every group-A pair is an exact name match.
--   · group B from the archived page's own <title>, checked to name the expected bill.
--
-- ⚠ A 200 FROM THIS SITE DOES NOT MEAN THE PAGE EXISTS, AND THAT CUTS BOTH WAYS. The 08-02 sweep marked
-- 16 of these URLs "200/OK" and they are the group-C redirects -- real, not soft-404s. The other 26
-- serve a genuine 404 with a ~7.5KB not-found shell. Status code and existence were measured separately
-- because a Gatsby/WordPress site can serve either one dressed as the other.
--
-- ⚠ FOUR CITED SLUGS NAME BILLS ACT ON MASS NEVER TRACKED, and are deliberately left dead (15 rows):
--   · /bills/the-roe-act -- rows cite "the ROE Act (H.3320 / S.1209)", the 2019-20 bill; the site tracks
--     the later Abortion Access Act. Different bills.
--   · /bills/universal-childcare -- rows cite "the Affordable and Accessible Child Care for All Act";
--     the site's Campaign Childcare is childcare for CANDIDATES. Different bills.
--   · /bills/rent-control -- rows cite "the Rent Stabilization Act"; the site's campaign is "Lift the Ban
--     on Local Tenant Protections". Related, not identical.
--   · /bills/racially-inclusive-education -- not confidently the CARE Act.
--   None of the four was ever captured by Wayback under that slug, which is consistent with the URL
--   having been composed rather than visited. Mapping them would assert an identity no source supports.
--
-- ⚠ TWO cited slugs never existed but ARE the same bill under a shorter name, and are re-pointed at the
-- real page's capture: /bills/100-renewable-energy (rows: "the 100% Renewable Energy Act") and
-- /bills/cherish-act (row: "the Cherish Act"). The distinction from the four above is that the archive
-- holds a page whose title names exactly the bill the rows name.
--
-- ⚠ The live bill pages carry "HOUSE COSPONSORS / SENATE COSPONSORS" headings whose NAMES are not in the
-- served HTML (JS-gated), so a reader checking a co-sponsorship claim cannot do it from a group-A/C
-- link alone. That is acceptable here: 111 of the 196 rows on dead URLs also cite a legislator
-- scorecard -- re-pointed to Wayback by 1532 -- and only 10 are sole-sourced. The bill citation's job on
-- these rows is to identify the bill, which the live page does better than the archive.

BEGIN;

CREATE TEMP TABLE aomb_map(old text PRIMARY KEY, new text NOT NULL, expected int NOT NULL, grp text NOT NULL) ON COMMIT DROP;

INSERT INTO aomb_map(old, new, expected, grp) VALUES
  -- A: live page "Right to Strike"
  ('https://actonmass.org/bills/the-right-to-strike/',
   'https://actonmass.org/right-to-strike/', 5, 'A'),
  -- A: live page "Abortion Access Act"
  ('https://actonmass.org/bills/abortion-protection/',
