  ('https://actonmass.org/bills/climate-superfund/',
   'https://actonmass.org/climate-change-superfund/', 9, 'A'),
  -- B: archive "Campaign Childcare | Act On Mass"
  ('https://actonmass.org/bills/campaign-childcare/',
   'https://web.archive.org/web/20260510031025/https://actonmass.org/bills/campaign-childcare/', 14, 'B'),
  -- A: live page "CARE Act"
  ('https://actonmass.org/bills/commission-for-anti-racism-and-equity-in-education/',
