  -- A: live page "Climate Change Superfund (rows name it "Polluter Pays / Climate Superfund Act (H.872 / S.481)")"
  ('https://actonmass.org/bills/polluter-pays/',
   'https://actonmass.org/climate-change-superfund/', 7, 'A'),
  -- C: site 301 -> https://actonmass.org/prison-moratorium/
  ('https://actonmass.org/bills/prison-moratorium',
   'https://actonmass.org/prison-moratorium/', 5, 'C'),
  -- C: site 301 -> https://actonmass.org/voting-rights-restoration/
  ('https://actonmass.org/bills/voting-rights-restoration/',
   'https://actonmass.org/voting-rights-restoration/', 1, 'C'),
  -- B: archive "Fair Scheduling | Act On Mass"
  ('https://actonmass.org/bills/fair-scheduling/',
   'https://web.archive.org/web/20230204184444/https://actonmass.org/bills/fair-scheduling/', 5, 'B'),
  -- B: archive "The Cherish Act: Fully Funded Public Higher Ed | Act On Mass"
  ('https://actonmass.org/bills/cherish-act-fully-funded-public-higher-ed/',
   'https://web.archive.org/web/20260310191126/https://actonmass.org/bills/cherish-act-fully-funded-public-higher-ed/', 18, 'B'),
  -- B: archive "Ranked Choice Voting | Act On Mass"
  ('https://actonmass.org/bills/ranked-choice-voting/',
   'https://web.archive.org/web/20230528153936/https://actonmass.org/bills/ranked-choice-voting/', 1, 'B'),
  -- B: archive "Right to Unionize for Ride Share Drivers | Act On Mass"
  ('https://actonmass.org/bills/right-to-unionize-for-ride-share-drivers/',
   'https://web.archive.org/web/20260212211836/https://actonmass.org/bills/right-to-unionize-for-ride-share-drivers/', 1, 'B'),
  -- B: archive "100% Renewable Energy by 2045 | Act On Mass"
  ('https://actonmass.org/bills/100-renewable-energy-by-2045/',
   'https://web.archive.org/web/20260412020611/https://actonmass.org/bills/100-renewable-energy-by-2045/', 9, 'B'),
  -- B: archive "Fair Share Amendment | Act On Mass"
  ('https://actonmass.org/bills/fair-share-amendment/',
   'https://web.archive.org/web/20241031035849/https://actonmass.org/bills/fair-share-amendment/', 1, 'B'),
  -- C: site 301 -> https://actonmass.org/indigenous-peoples-day/
