  -- B: archive "Work & Family Mobility Act | Act On Mass"
  ('https://actonmass.org/bills/driver-license-regardless-immigration-status/',
   'https://web.archive.org/web/20241031040959/https://actonmass.org/bills/driver-license-regardless-immigration-status/?utm_medium=&emci=62e031af-0fef-ec11-b47a-281878b83d8a&emdi=f18f9377-2cef-ec11-b47a-281878b83d8a&ceid=21506428', 6, 'B'),
  -- C: site 301 -> https://actonmass.org/stop-corporate-offshoring/
  ('https://actonmass.org/bills/stop-corporate-offshoring/',
   'https://actonmass.org/stop-corporate-offshoring/', 1, 'C'),
  -- C: site 301 -> https://actonmass.org/overdose-prevention-centers/
  ('https://actonmass.org/bills/overdose-prevention-centers/',
   'https://actonmass.org/overdose-prevention-centers/', 10, 'C'),
  -- C: site 301 -> https://actonmass.org/life-without-parole/
  ('https://actonmass.org/bills/life-without-parole/',
   'https://actonmass.org/life-without-parole/', 6, 'C'),
  -- A: live page "Healthy Youth Act"
  ('https://actonmass.org/bills/healthy-youth-act/',
   'https://actonmass.org/healthy-youth/', 8, 'A'),
  -- C: site 301 -> https://actonmass.org/medicare-for-all/
  ('https://actonmass.org/bills/medicare-for-all/',
   'https://actonmass.org/medicare-for-all/', 16, 'C'),
  -- A: live page "Safe Communities Act"
  ('https://actonmass.org/bills/safe-communities-act/',
