  -- C: site 301 -> https://actonmass.org/age-of-criminal-majority-to-21-raise-the-age/
  ('https://actonmass.org/bills/age-of-criminal-majority-to-21/',
   'https://actonmass.org/age-of-criminal-majority-to-21-raise-the-age/', 10, 'C'),
  -- C: site 301 -> https://actonmass.org/sunlight-act/
  ('https://actonmass.org/bills/sunlight-act',
   'https://actonmass.org/sunlight-act/', 1, 'C'),
