   'https://actonmass.org/abortion-access-act/', 4, 'C'),
  -- C: site 301 -> https://actonmass.org/overdose-prevention-centers/
  ('https://actonmass.org/bills/overdose-prevention-centers',
   'https://actonmass.org/overdose-prevention-centers/', 1, 'C'),
  -- B: archive "The Cherish Act: Fully Funded Public Higher Ed | Act On Mass" (cited slug never existed; real slug /bills/cherish-act-fully-funded-public-higher-ed)
  ('https://actonmass.org/bills/cherish-act/',
   'https://web.archive.org/web/20260310191126/https://actonmass.org/bills/cherish-act-fully-funded-public-higher-ed/', 1, 'B'),
  -- A: live page "Safe Communities Act"
  ('https://actonmass.org/bills/safe-communities-act',
   'https://actonmass.org/safe-communities/', 19, 'A'),
  -- A: live page "Lift the Ban on Local Tenant Protections"
  ('https://actonmass.org/bills/end-home-rule/',
   'https://actonmass.org/lift-the-ban-on-local-tenant-protections/', 2, 'A'),
  -- C: site 301 -> https://actonmass.org/stop-wage-theft/
  ('https://actonmass.org/bills/stop-wage-theft/',
   'https://actonmass.org/stop-wage-theft/', 17, 'C'),
  -- B: archive "100% Renewable Energy by 2045 | Act On Mass" (cited slug never existed; real slug /bills/100-renewable-energy-by-2045)
  ('https://actonmass.org/bills/100-renewable-energy/',
   'https://web.archive.org/web/20260412020611/https://actonmass.org/bills/100-renewable-energy-by-2045/', 13, 'B'),
  -- C: site 301 -> https://actonmass.org/sunlight-act/
  ('https://actonmass.org/bills/sunlight-act/',
   'https://actonmass.org/sunlight-act/', 2, 'C'),
  -- B: archive "The THRIVE Act | Act On Mass"
  ('https://actonmass.org/bills/moratorium-on-high-stakes-testing/',
   'https://web.archive.org/web/20260119054547/https://actonmass.org/bills/moratorium-on-high-stakes-testing/', 2, 'B');

-- 🔴 NOT array_replace. 35 of these rows cite TWO OR THREE mapped URLs, and array_replace substitutes
-- one value per call -- it would leave the second and third citation dead. This maps every element of
-- the array in a single pass, preserving original order, and de-duplicates because two source URLs can
-- share one target: 6 row(s) cite both /bills/polluter-pays and /bills/climate-superfund, which are
-- the same bill (the rows themselves call it "the Polluter Pays / Climate Superfund Act (H.872/S.481)").
-- ⚠ Safe to de-duplicate only because no affected row contains a pre-existing duplicate source --
-- checked, zero, and re-checked at generation time.
UPDATE inform.politician_context pc
   SET sources = ARRAY(
         SELECT v FROM (
           SELECT coalesce(m.new, u.s) AS v, min(u.ord) AS ord
             FROM unnest(pc.sources) WITH ORDINALITY AS u(s, ord)
             LEFT JOIN aomb_map m ON m.old = u.s
            GROUP BY 1
         ) z ORDER BY z.ord)
 WHERE EXISTS (SELECT 1 FROM unnest(pc.sources) s JOIN aomb_map m ON m.old = s);

DO $$
DECLARE v_n int; v_bad text;
BEGIN
  -- 1. Per-TARGET counts, scoped to (politician_id, topic_id). ⚠ Counted as DISTINCT rows, not as the
  --    sum of the source URLs' counts: three targets are fed by two source URLs each (the
  --    safe-communities-act slash pair, and polluter-pays + climate-superfund, which are one bill), so
  --    summing double-counts every row that cites both. /climate-change-superfund/ sums to 16; the
  --    true post-state is 11, and the first dry run failed on exactly that.
  SELECT string_agg(format('%s: expected %s, found %s', t.new, t.expected, x.n), E'\n') INTO v_bad
    FROM (VALUES
      ('https://actonmass.org/abortion-access-act/', 10),
      ('https://actonmass.org/age-of-criminal-majority-to-21-raise-the-age/', 10),
      ('https://actonmass.org/care-act/', 2),
      ('https://actonmass.org/climate-change-superfund/', 11),
      ('https://actonmass.org/healthy-youth/', 8),
      ('https://actonmass.org/indigenous-peoples-day/', 1),
      ('https://actonmass.org/life-without-parole/', 6),
      ('https://actonmass.org/lift-the-ban-on-local-tenant-protections/', 2),
      ('https://actonmass.org/medicare-for-all/', 24),
      ('https://actonmass.org/overdose-prevention-centers/', 11),
      ('https://actonmass.org/prison-moratorium/', 24),
      ('https://actonmass.org/right-to-strike/', 5),
      ('https://actonmass.org/safe-communities/', 56),
      ('https://actonmass.org/stop-corporate-offshoring/', 1),
      ('https://actonmass.org/stop-wage-theft/', 17),
      ('https://actonmass.org/sunlight-act/', 3),
      ('https://actonmass.org/support-native-students/', 1),
      ('https://actonmass.org/voting-rights-restoration/', 1),
      ('https://web.archive.org/web/20230204184444/https://actonmass.org/bills/fair-scheduling/', 5),
      ('https://web.archive.org/web/20230528153936/https://actonmass.org/bills/ranked-choice-voting/', 1),
      ('https://web.archive.org/web/20241031035741/https://actonmass.org/bills/lower-voting-age-to-16/', 1),
      ('https://web.archive.org/web/20241031035849/https://actonmass.org/bills/fair-share-amendment/', 1),
      ('https://web.archive.org/web/20241031040959/https://actonmass.org/bills/driver-license-regardless-immigration-status/?utm_medium=&emci=62e031af-0fef-ec11-b47a-281878b83d8a&emdi=f18f9377-2cef-ec11-b47a-281878b83d8a&ceid=21506428', 6),
      ('https://web.archive.org/web/20260119054547/https://actonmass.org/bills/moratorium-on-high-stakes-testing/', 2),
      ('https://web.archive.org/web/20260212211836/https://actonmass.org/bills/right-to-unionize-for-ride-share-drivers/', 1),
      ('https://web.archive.org/web/20260310182638/https://actonmass.org/bills/environmental-justice/', 14),
      ('https://web.archive.org/web/20260310191126/https://actonmass.org/bills/cherish-act-fully-funded-public-higher-ed/', 19),
      ('https://web.archive.org/web/20260412020611/https://actonmass.org/bills/100-renewable-energy-by-2045/', 22),
      ('https://web.archive.org/web/20260510031025/https://actonmass.org/bills/campaign-childcare/', 14)
         ) AS t(new, expected)
    JOIN LATERAL (
      SELECT count(*)::int AS n FROM inform.politician_context pc
        JOIN inform.politician_answers pa
          ON pa.politician_id = pc.politician_id AND pa.topic_id = pc.topic_id AND pa.value <> 0
       WHERE t.new = ANY(pc.sources)) x ON true
   WHERE x.n <> t.expected;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'per-target count mismatch:%', E'\n' || v_bad; END IF;

  -- 2. Nothing still cites a re-pointed URL.
  SELECT count(*) INTO v_n FROM inform.politician_context pc
   WHERE EXISTS (SELECT 1 FROM unnest(pc.sources) s JOIN aomb_map m ON m.old = s);
  IF v_n <> 0 THEN RAISE EXCEPTION '% row(s) still cite a re-pointed URL', v_n; END IF;

  -- 3. Exactly the reviewed number of ROWS moved. ⚠ 243 rows, not the 284 row-CITATIONS: 35 rows
  --    cite two or three of these URLs, so the per-URL counts sum past the number of rows that exist.
  SELECT count(*) INTO v_n FROM inform.politician_context pc
    JOIN inform.politician_answers pa
      ON pa.politician_id = pc.politician_id AND pa.topic_id = pc.topic_id AND pa.value <> 0
   WHERE EXISTS (SELECT 1 FROM unnest(pc.sources) s JOIN aomb_map m ON m.new = s);
  IF v_n <> 243 THEN RAISE EXCEPTION 'expected 243 rows citing a new target, found %', v_n; END IF;

  -- 4. 🔴 The 15 held rows -- the four unidentifiable bills -- must be untouched.
  SELECT count(*) INTO v_n FROM inform.politician_context pc
    JOIN inform.politician_answers pa
      ON pa.politician_id = pc.politician_id AND pa.topic_id = pc.topic_id AND pa.value <> 0
   WHERE EXISTS (SELECT 1 FROM unnest(pc.sources) s WHERE s = ANY(ARRAY[
     'https://actonmass.org/bills/rent-control/',
     'https://actonmass.org/bills/racially-inclusive-education/',
     'https://actonmass.org/bills/universal-childcare/',
     'https://actonmass.org/bills/the-roe-act/'
   ]));
  IF v_n <> 15 THEN RAISE EXCEPTION 'held rows changed: expected 15, found %', v_n; END IF;

  -- 5. The cohort total after the rewrite: 284 citations + 15 held, minus the de-duplications.
  --    ⚠ The expected value is SIMULATED read-only against real data, not derived. Deriving it as
  --    (citations + held - 6 collapses) gave 293 and the truth is 294: a row that already cited
  --    the live target alongside the dead URL also collapses, which the collapse counter cannot see.
  SELECT count(*) INTO v_n FROM inform.politician_context pc
    JOIN inform.politician_answers pa
      ON pa.politician_id = pc.politician_id AND pa.topic_id = pc.topic_id AND pa.value <> 0
    CROSS JOIN LATERAL unnest(pc.sources) s
   WHERE s ILIKE '%actonmass.org/bills/%'
      OR s = ANY(SELECT new FROM aomb_map);
  IF v_n <> 294 THEN RAISE EXCEPTION 'bills-citation total drifted: expected 294, found %', v_n; END IF;

  -- 6. 🔴 The array rewrite touches EVERY element, not just the mapped ones, so prove it preserved the
  --    unmapped sources too: no affected row may have lost a citation it was not meant to lose.
  SELECT count(*) INTO v_n
    FROM inform.politician_context pc
